  async function scenario(name,fn,usesHarness=true){const before=assertions;h=usesHarness?harness():null;try{if(h)await h.mount();await fn();if(h){equal(h.eventErrors,[],'无未处理 DOM 错误');equal(h.network,0,'未触达实际 HTTP');equal(h.model,0,'未调用模型');}results.push({name,status:'passed',assertions:assertions-before});}
    catch(error){results.push({name,status:'failed',assertions:assertions-before,error:error.message,stack:error.stack});}
    finally{if(h){runs.push({scenario:name,requests:clone(h.requests),balances:[...h.balances],ledger:clone(h.ledger),operation_states:[...h.operations.values()].map(op=>({id:op.operation.id,state:op.operation.state,owner:op.owner,kind:op.aa.kind})),network_requests:h.network,model_calls:h.model,event_errors:h.eventErrors});await h.close();h=null;}}}

